pageControlPressed = pyqtSignal(dict)

@pyqtSlot(str)
def controlPressed(self, payload: str = "") -> None:
    self.pageControlPressed.emit(self._payload(payload))  # nothing is returned to the page

def _on_page_control_pressed(self, payload: dict) -> None:
    data = payload if isinstance(payload, dict) else {}
    control = str(data.get("control") or "")
    if control not in CONTROL_IDS:
        return               # a stale page must never raise across the bridge
    result = self.handle_control(control, data.get("value"))
    if result.get("refused"):
        self.zoom_refused.emit()   # exactly once; the page cannot see the answer

function controlPressed(controlId, value) {
  if (chart) {
    if (controlId === "zoom-in" || controlId === "zoom-out") {
      var range = chart.timeScale().getVisibleLogicalRange();
      if (range) zoom(range, controlId === "zoom-in" ? 0.8 : 1.25);
    } else if (controlId === "reset") {
      fitAndFollow();
    }
  }
  var target = pageBridgeTarget();   // lazy window.lwBridge lookup (the reportKey pattern)
  if (target && typeof target.controlPressed === "function") {
    target.controlPressed(JSON.stringify({ control: String(controlId), value: value }));
  }
  return undefined;                  // the production shape the latch rule depends on
}

function mountControlCluster() {
  var container = document.getElementById("controls");
  var li = moduleHandle("LwInteraction");
  if (!container || !li || typeof li.mountControls !== "function") return [];
  return li.mountControls(container, controlPressed);
}

// click handler: no optimistic write. Three branches on the result:
//   refused (TR-9)          -> restore the pre-click value: btn.setAttribute("aria-pressed", value ? "false" : "true")
//   synchronous result.mode -> btn.setAttribute("aria-pressed", result.mode === "ZOOMING" ? "true" : "false")
//   no synchronous answer   -> leave the attribute; the router_mode op drives it via syncControlState
// plus `if (container.__lwControls) return container.__lwControls;` / `container.__lwControls = made;`
// guard extension: if (!container || typeof container.appendChild !== "function" || typeof document === "undefined") return [];

function syncControlState(op) {
  if (!op || (op.op !== "router_mode" && op.op !== "reset_view") || typeof op.mode !== "string") return false;
  // when document exists: getElementById("control-magnifier").setAttribute("aria-pressed", op.mode === "ZOOMING" ? "true" : "false")
  // return true; false when nothing is mounted. A `zoom` op carries no mode and changes nothing.
}

// in applyChannel's `interaction` branch, after the mode/tool bookkeeping and BEFORE gestures.applyRouterOp(op):
var li2 = moduleHandle("LwInteraction");
if (li2 && typeof li2.syncControlState === "function") li2.syncControlState(op);
